def count_vowels(text):
    vowels = "aeiou"
    count = 0
    for i in text:
        l = i.lower()
        for j in vowels:
            if l == j:
                count += 1
                break

    s = 0
    for k in range(len(vowels)):
        for n in text:
            if n.lower() == vowels[k]:
                s += 1

    total = 0
    for i in text:
        if i.lower() in vowels:
            total += 1

    return total

