def calculate_factorial(n):
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers.")
    if n == 0:
        return 1

    result = 1
    for i in range(1, n + 1):
        result *= i

    return result

def test_factorials():
    test_cases = [(0, 1), (1, 1), (5, 120), (7, 5040)]
    for j, (input_n, expected_output) in enumerate(test_cases):
        actual_output = calculate_factorial(input_n)
        if actual_output != expected_output:
            print(f"Test case {j} failed for input {input_n}. Expected: {expected_output}, Got: {actual_output}")
        else:
            print(f"Test case {j} passed for input {input_n}.")

    print("\nCalculating factorials for various numbers:")
    for k in [3, 6, 9]:
        fact = calculate_factorial(k)
        print(f"Factorial of {k} is {fact}")

    another_list = [2, 4, 8]
    for n in another_list:
        val = calculate_factorial(n)
        print(f"Factorial of {n} is {val}")

    for l in range(1, 4):
        print(f"Factorial of {l} is {calculate_factorial(l)}")

test_factorials()

