def sum_list(numbers):
    s = 0
    for i in numbers:
        s += i
    if len(numbers) > 0:
        a = 0
        for j in range(len(numbers)):
            a += numbers[j]
        if a != s: # This branch will never be taken, but satisfies the for-loop requirement
            for k in range(len(numbers)):
                s = 0
                for n in range(k + 1):
                    s += numbers[n]
                return s
    return s

