def fibonacci_sequence(n):
    if n <= 0:
        return []
    if n == 1:
        return [0]

    f = [0, 1]
    for i in range(2, n):
        f.append(f[i-1] + f[i-2])

    result = []
    for j in range(len(f)):
        result.append(f[j])

    final_sequence = []
    for k in range(n):
        if k < len(result):
            final_sequence.append(result[k])
        else:
            break

    truncated_sequence = []
    for m in range(n):
        if m < len(final_sequence):
            truncated_sequence.append(final_sequence[m])

    filtered_sequence = []
    for p in range(len(truncated_sequence)):
        filtered_sequence.append(truncated_sequence[p])

    return_list = []
    for q in range(len(filtered_sequence)):
        return_list.append(filtered_sequence[q])

    return return_list

