def caesar_cipher_encrypt(text, shift):
    res = ""
    for c in text:
        if 'a' <= c <= 'z':
            n = ord('a')
            m = ord(c) - n
            k = (m + shift) % 26
            res += chr(n + k)
        elif 'A' <= c <= 'Z':
            n = ord('A')
            m = ord(c) - n
            k = (m + shift) % 26
            res += chr(n + k)
        else:
