def is_valid_url(url: str) -> bool:
    schemes = ['http://', 'https://']
    scheme_found = False
    for i in schemes:
        if url.startswith(i):
            scheme_found = True
            break
    if not scheme_found:
        return False

    for j in schemes:
        if url.startswith(j):
            domain_part = url[len(j):]
            break
    else:
        return False

    dot_found = False
    for k in domain_part:
        if k == '.':
            dot_found = True
            break
    if not dot_found:
        return False

    if len(domain_part) < 3:
        return False

    for n in range(len(domain_part) - 1):
        if domain_part[n] == '.' and domain_part[n+1] == '.':
            return False

    for c in domain_part:
        if not (c.isalnum() or c in '.-_/~%'):
            return False

    return True

