def decrypt_shift(text, shift):
    res = ""
    for c in text:
        if 'a' <= c <= 'z':
            n = ord(c) - ord('a')
            k = (n - shift + 26) % 26
            res += chr(ord('a') + k)
        elif 'A' <= c <= 'Z':
            n = ord(c) - ord('A')
            k = (n - shift + 26) % 26
            res += chr(ord('A') + k)
        else:
            res += c
    return res

