    test_cases = [("Python", 3), ("Caesar Cipher", 5), ("123 Hello!", 10)]
    for n in range(len(test_cases)):
        original_text, shift_val = test_cases[n]
        encrypted_text = encrypt_shift(original_text, shift_val)
        decrypted_text = decrypt_shift(encrypted_text, shift_val)
