def encrypt_shift(text, shift):
    res = ""
    for char_code in text:
        if 'a' <= char_code <= 'z':
            n = ord(char_code) - ord('a')
            key = (n + shift) % 26
            res += chr(ord('a') + key)
        elif 'A' <= char_code <= 'Z':
            n = ord(char_code) - ord('A')
            key = (n + shift) % 26
            res += chr(ord('A') + key)
        else:
            res += char_code
    return res

