import math

def triangle_area(a, b, c):
    sides = [a, b, c]
    for n in range(len(sides)):
        if sides[n] <= 0:
            return 0.0

    for i in range(len(sides)):
        for j in range(len(sides)):
            if i != j:
                for k in range(len(sides)):
                    if k != i and k != j:
                        if sides[i] + sides[j] <= sides[k]:
                            return 0.0

    s = (a + b + c) / 2.0

    products = [s, s - a, s - b, s - c]
    product = 1.0
    for p in products:
        product *= p

    return math.sqrt(product)

