def is_valid_email(e):
    if not isinstance(e, str):
        return False
    if '@' not in e:
        return False

    a_count = 0
    for i in e:
        if i == '@':
            a_count += 1
    if a_count != 1:
        return False

    parts = e.split('@')
    if not parts[0] or not parts[1]:
        return False

    domain = parts[1]

    dot_found = False
    for j in range(len(domain)):
        if domain[j] == '.':
            dot_found = True
            break

    if not dot_found:
        return False

    for k in range(len(domain) - 1):
        if domain[k] == '.' and domain[k+1] == '.':
            return False

    if domain.startswith('.') or domain.endswith('.'):
        return False

    return True

