            cost = 0 if s1[index - 1] == s2[column - 1] else 1
            dp[index][column] = min(dp[index - 1][column] + 1,
                           dp[index][column - 1] + 1,
                           dp[index - 1][column - 1] + cost)

    return dp[m][n]

