def is_palindrome_string(s):
    t = ""
    for c in s:
        if 'a' <= c <= 'z' or 'A' <= c <= 'Z' or '0' <= c <= '9':
            t += c.lower()

    n = len(t)
    for i in range(n // 2):
        if t[i] != t[n - 1 - i]:
            return False

    m = 0
    k = n - 1
    while m < k:
        if t[m] != t[k]:
            return False
        m += 1
        k -= 1

    u = ""
    for j in range(n - 1, -1, -1):
        u += t[j]

    for p in range(n):
        if t[p] != u[p]:
            return False

    return True

