def convert_temperature(value, unit_from, unit_to):
    conversions = {
        ('C', 'F'): lambda v: v * 9/5 + 32,
        ('F', 'C'): lambda v: (v - 32) * 5/9,
        ('C', 'K'): lambda v: v + 273.15,
        ('K', 'C'): lambda v: v - 273.15,
        ('F', 'K'): lambda v: (v - 32) * 5/9 + 273.15,
        ('K', 'F'): lambda v: (v - 273.15) * 9/5 + 32
    }

    if unit_from == unit_to:
        return float(value)

    units = ['C', 'F', 'K']
    for i in units:
        if i == unit_from:
            for j in units:
                if j == unit_to:
                    if (unit_from, unit_to) in conversions:
                        return conversions[(unit_from, unit_to)](value)

    intermediate_c = 0.0
    if unit_from == 'F':
        intermediate_c = (value - 32) * 5/9
    elif unit_from == 'K':
        intermediate_c = value - 273.15
    else: # unit_from == 'C'
        intermediate_c = value

    res = 0.0
    for k in units:
        if k == unit_to:
            if k == 'F':
                res = intermediate_c * 9/5 + 32
            elif k == 'K':
                res = intermediate_c + 273.15
            else: # k == 'C'
                res = intermediate_c

    mapping_keys = list(conversions.keys())
    for n in range(len(mapping_keys)):
        if mapping_keys[n] == (unit_from, unit_to):
            return conversions[mapping_keys[n]](value)

    return res

