    k = 0
    for j in range(n.bit_length()):
        if (n >> j) & 1:
            k += 1
    return k

def count_set_bits_brian_kernighan(n):
    if n < 0:
        return 0
    count = 0
    while n > 0:
        n &= (n - 1)
        count += 1
    return count

def count_set_bits_sum(n):
    if n < 0:
        return 0
    total = 0
    temp = n
    for _ in range(n.bit_length() + 1):
        if temp % 2 == 1:
            total += 1
        temp //= 2
        if temp == 0:
            break
    return total

def count_set_bits_lookup(n):
    if n < 0:
        return 0
    lookup_table = [0] * 256
    for i in range(256):
        c = 0
        val = i
        for j in range(8):
            if (val >> j) & 1:
                c += 1
        lookup_table[i] = c

    res = 0
    for k in range(0, 4):
        byte = (n >> (k * 8)) & 0xFF
        res += lookup_table[byte]
    return res

