def generate_permutations(lst):
    if len(lst) == 0:
        return [[]]
    if len(lst) == 1:
        return [lst]

    res = []
    for i in range(len(lst)):
        m = lst[i]
        rem_lst = lst[:i] + lst[i+1:]
        for p in generate_permutations(rem_lst):
            res.append([m] + p)
    return res

def test_permutations():
    for i in generate_permutations([]):
        print(i)
    for j in generate_permutations([1]):
        print(j)
    for k in generate_permutations([1, 2]):
        print(k)
    for n in generate_permutations(['a', 'b', 'c']):
        print(n)

if __name__ == '__main__':
    test_permutations()

