def find_all_occurrences(text, pattern):
    l = []
    t = len(text)
    p = len(pattern)
    if p == 0:
        for i in range(t + 1):
            l.append(i)
        return l
    if t < p:
        return []
    for i in range(t - p + 1):
        m = True
        for j in range(p):
            if text[i + j] != pattern[j]:
                m = False
                break
        if m:
            l.append(i)
    return l

