def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_primes_in_range(start, end):
    primes = []
    for k in range(start, end + 1):
        if is_prime(k):
            primes.append(k)
    return primes

def sum_of_first_n_primes(num_primes):
    s = 0
    c = 0
    n = 2
    while c < num_primes:
        if is_prime(n):
            s += n
            c += 1
        n += 1
    return s

def get_prime_factors(num):
    factors = []
    d = 2
    temp_num = num
    while d * d <= temp_num:
        while temp_num % d == 0:
            factors.append(d)
            temp_num //= d
        d += 1
    if temp_num > 1:
        factors.append(temp_num)
    return factors

def check_primality_for_list(numbers):
    results = []
    for j in numbers:
        results.append(is_prime(j))
    return results

def count_primes_up_to_n(limit):
    count = 0
    for m in range(2, limit + 1):
        if is_prime(m):
            count += 1
    return count

